import { type ColorTokens, scales, themes } from "./tokens";

const indent = (lines: string[], depth: number) => lines.map((l) => `${"  ".repeat(depth)}${l}`);
const colorLines = (theme: ColorTokens) =>
  Object.entries(theme).map(([k, v]) => `--color-${k}: ${v};`);
const scaleLines = () =>
  Object.entries(scales).flatMap(([group, values]) =>
    Object.entries(values).map(([k, v]) => `--${group}-${k}: ${v};`),
  );

/** The full contents of tokens.css. Pure, so a test can assert the committed file is current. */
export function renderTokensCss(): string {
  return [
    "/* GENERATED by `pnpm --filter @repo/ui tokens:build` from src/tokens/tokens.ts — do not edit. */",
    "",
    ":root {",
    ...indent(scaleLines(), 1),
    "}",
    "",
    ':root,\n[data-theme="light"] {',
    ...indent(["color-scheme: light;", ...colorLines(themes.light)], 1),
    "}",
    "",
    "/* System preference, unless the page pins light with data-theme. */",
    "@media (prefers-color-scheme: dark) {",
    '  :root:not([data-theme="light"]) {',
    ...indent(["color-scheme: dark;", ...colorLines(themes.dark)], 2),
    "  }",
    "}",
    "",
    '[data-theme="dark"] {',
    ...indent(["color-scheme: dark;", ...colorLines(themes.dark)], 1),
    "}",
    "",
  ].join("\n");
}
